u=DraftUnit('U04','位置與存在：在小鎮找到你');p=u.pack;q=u.question
words=[('うえ','上面'),('した','下面'),('なか','裡面'),('そと','外面'),('まえ','前面'),('うしろ','後面'),('みぎ','右邊'),('ひだり','左邊'),('となり','旁邊／相鄰'),('ちかく','附近'),('あいだ','中間'),('ここ','這裡，靠說話者'),('そこ','那裡，靠聽話者'),('あそこ','那裡，離雙方都遠'),('どこ','哪裡'),('へや','房間'),('にわ','庭院'),('こうえん','公園'),('えき','車站'),('みせ','商店'),('トイレ','廁所'),('ベッド','床'),('テレビ','電視'),('ある','有／存在，用於物品；禮貌形あります'),('いる','有／在，用於人或動物；禮貌形います')]
