p['grammar']=[dict(id=g,title=t,prerequisites=['K-HIRA',dep]) for g,t,dep in [('G10','人／動物います，物品あります','G09'),('G11','場所にNがあります／います','G10'),('G12','Nは場所にあります／います','G11')]]
for n,(start,end,title,titleja) in enumerate([(0,5,'上下裡外與前面','うえ・した・なか・そと・まえ'),(5,10,'後面與附近','うしろ・みぎ・ひだり・となり・ちかく'),(10,15,'指向哪裡','ばしょをさすことば'),(15,20,'小鎮裡的地方','まちのばしょ'),(20,25,'看得到的物品與生命','ものとひと・どうぶつ')],1):
 vs=p['vocabulary'][start:end];body='\n'.join(f"{v['text']}：{v['meaning']}" for v in vs)
 if n==2:body+='\nみぎ／ひだり先確定共同面向；相鄰才是となり，只說附近用ちかく。'
 if n==3:body+='\nここ靠我、そこ靠你、あそこ離我們都遠。兩者中間可說AとBのあいだ；と在這裡把兩個地方連起來。'
 script='。'.join({'ある':'あります','いる':'います'}.get(v['text'],v['reading']) for v in vs)+'。'
 id=u.teach(f'words-{n}',title,titleja,body,'ことばをきいて、ばしょやものをたしかめよう。',vs[0]['text'],vs[0]['meaning'],['V-CONTEXT','V-PARA','K-HIRA','K-KATA'],script,vocabularyIds=[v['id'] for v in vs]);u.wordcards.append(id)
u.teach('kanji','把位置讀出來','ばしょのかんじ','上（うえ）、下（した）、中（なか）、外（そと）、前（まえ）。\n物品＋の＋位置：つくえの上＝桌子上面；はこの中＝箱子裡。\n這一課使用位置的讀音，不能把「上」讀成うしろ。','上はうえ、下はした、中はなか、外はそと、前はまえです。','つくえの 上（うえ）／はこの 中（なか）','桌子上面／箱子裡面。',['K-SCRIPT'],'うえ。した。なか。そと。まえ。つくえのうえ。はこのなか。',kanjiIds=[k['id'] for k in p['kanji']],prerequisites=u.wordcards)
u.teach('G10','有人、有動物、有東西','います・あります','人或動物用います；物品用あります。\n正例：ねこが います（有貓）；ほんが あります（有書）。\n反例：ほんがいます把書當成人或動物，應說ほんがあります。\n沒有動物用いません；沒有物品用ありません。不要把あります改成ありますません。\nだれ表示誰，なに表示什麼；質問「なにが ありますか」詢問有什麼物品。','ひととどうぶつには、います。ものには、あります。ねこがいます。ほんがあります。','いぬが います。かばんが あります。','有狗；有書包。',['G10'],'ねこがいます。いぬがいます。せんせいがいます。ほんがあります。かばんがあります。ねこはいません。ほんはありません。',grammarIds=['G10'],prerequisites=['U04-teach-kanji'])
u.teach('G11','先說地方，再介紹有什麼','ばしょに、なにがありますか','場所＋に＋人／物＋が＋います／あります。\n正例：にわに いぬが います；つくえの上に ほんが あります。\n場所後面用に；介紹存在的人或物用が。\n反例：にわが いぬに います，把兩個助詞的位置反了。先找哪裡、再找有誰。','ばしょに、ひとやものが、います・あります。','へやに せんせいが います。','房間裡有老師。',['G11'],'にわに、いぬがいます。つくえのうえに、ほんがあります。へやに、せんせいがいます。',grammarIds=['G11'],prerequisites=['U04-teach-G10'])
u.teach('G12','先說要找的東西，再說在哪裡','どこにありますか','人／物＋は＋場所＋に＋います／あります。\n正例：ねこは つくえの下に います；かばんは はこの中に あります。\n問法：ほんは どこに ありますか（書在哪裡？）。\n反例：ねこはつくえの下があります，少了場所後的に，也選錯あります。\n先說尋找對象，用は；用に標位置，最後依對象決定います或あります。','さがすひとやものを、はでしめします。つぎに、ばしょに、います・あります。','ほんは いすの 上（うえ）に あります。','書在椅子上。',['G12'],'ねこは、つくえのしたにいます。かばんは、はこのなかにあります。ほんは、どこにありますか。いすのうえにあります。',grammarIds=['G12'],prerequisites=['U04-teach-G11'])
u.teach('story','找到對象，再確認位置','だれ・なに・どこ','表格中的左欄是對象、右欄是位置。\n尋物先看是誰／什麼，再看在哪裡。同一個房間裡，書可以在桌上，貓可以在桌下。\n門前表示門在動物後方；箱子中表示箱壁包住物品下半部。不要只因東西彼此靠近就判成裡面。\nねこはどこですか也能問貓在哪裡，完整回答可用ねこは～にいます。\n注意：同樣是問位置，最後仍依人／動物或物品選對存在動詞。','なにをさがすかを、さきにたしかめます。つぎに、ばしょをみましょう。','ねこは どこに いますか。つくえの 下（した）に います。','貓在哪裡？在桌子下面。',['R-SHORT','R-MID','R-INFO','L-TASK','L-KEY','L-EXPR','L-RESP','G-ORDER','G-TEXT'],'ねこは、どこにいますか。つくえのしたにいます。ほんは、どこにありますか。いすのうえにあります。',prerequisites=['U04-teach-G12'])
readings=[('へやに つくえと いすが あります。ほんは いすの上に あります。ねこは つくえの下に います。','R-SHORT'),('いぬは にわに います。にわは へやの外に あります。せんせいは きょうしつに います。かばんは へやのはこの中に あります。いぬは へやには いません。','R-MID'),('小鎮位置表\nみせ｜えきのとなり\nこうえん｜みせのうしろ\nトイレ｜こうえんの中\nせんせい｜こうえん','R-INFO'),('ユイ：かばんは どこに ありますか。いすの上ですか。\nアキ：いいえ。はこは つくえの みぎに あります。かばんは そのはこの中に あります。\nユイ：ねこは どこに いますか。\nアキ：つくえの下に います。','R-MID')]
p['readings']=[dict(id=f'U04-R{i:02}',text=t,skillId=skill) for i,(t,skill) in enumerate(readings,1)]
clips=[('ねこは、つくえのしたにいます。ほんは、いすのうえにあります。','L-KEY'),('いぬは、にわにいます。ともだちは、へやのなかにいます。いぬは、へやにはいません。','L-TASK'),('みせは、えきのとなりにあります。こうえんは、みせのうしろにあります。せんせいは、こうえんにいます。','L-KEY'),('ねこは、つくえのしたにいます。いぬは、ドアのまえにいます。ほんは、つくえのうえにあります。かばんは、はこのなかにあります。','L-EXPR'),('ねこは、どこにいますか。','L-RESP'),('はこのなかに、なにがありますか。','L-RESP')]
